var student = new Student() { StudentId = 1 };

using (var context = new SchoolContext())
{
    context.Remove<Student>(student);

    // or: context.Students.Remove(student);
    // or: context.Attach<Student>(student).State = EntityState.Deleted;
    // or: context.Entry<Student>(student).State = EntityState.Deleted;

    context.SaveChanges();
}

var students = new List<Student>() {
    new Student(){ StudentId = 1 },
    new Student(){ StudentId = 2 },
    new Student(){ StudentId = 3 },
    new Student(){ StudentId = 4 }
};

using (var context = new SchoolContext())
{
    context.RemoveRange(students);
    context.SaveChanges();
}
